// GOOD CODE: Demonstrates proper use of Java API to prevent SQL Injection
import java.sql.Connection;
import java.sql.DriverManager;
import java.sql.PreparedStatement;
import java.sql.ResultSet;

public class SecureLogin {
    public boolean checkUser(String username, String password) throws Exception {
        // This code is secure because it uses PreparedStatement with parameterized queries
        Connection conn = DriverManager.getConnection("jdbc:mysql://localhost:3306/mydb", "user", "pass");

        // Proper use of API: Using PreparedStatement prevents SQL injection by separating code from data
        String query = "SELECT * FROM users WHERE username=? AND password=?";
        PreparedStatement pstmt = conn.prepareStatement(query);

        // Set parameters safely, ensuring user input is treated as data, not executable code
        pstmt.setString(1, username);
        pstmt.setString(2, password);

        ResultSet rs = pstmt.executeQuery();
        boolean isValid = rs.next();

        // Close resources properly to prevent resource leaks
        rs.close();
        pstmt.close();
        conn.close();

        return isValid;
    }
}
